 import { createRequire } from "node:module";
 import { copyFileSync, existsSync, mkdirSync } from "node:fs";
 import { tmpdir } from "node:os";
 import { join } from "node:path";

 const require = createRequire(import.meta.url);

 export const MAX_FILE_SIZE_BYTES = 30 * 1024 * 1024; // 30 MB
 export const MAX_PDF_PAGES = 100;
 export const MAX_RENDER_PIXELS = 8 * 1024 * 1024; // 8M pixels
 export const MAX_PAGE_CHARS = 50_000; // 50k chars per page
 export const OCR_SPARSE_THRESHOLD_CHARS = 50;
 export const OCR_PAGE_TIMEOUT_MS = 45_000;

 export interface PdfPageResult {
   page: number;
   text: string;
   method: "text" | "ocr";
   confidence?: number;
 }

 export interface ReadPdfOptions {
   signal?: AbortSignal;
   log?: (message: string) => void;
 }

 export interface ReadPdfOutput {
   pages: PdfPageResult[];
   notes: string[];
 }

 export const isPdfMagic = (b: Uint8Array): boolean =>
   b.length >= 4 && b[0] === 0x25 && b[1] === 0x50 && b[2] === 0x44 && b[3] === 0x46; // %PDF

 export function isPdfCandidate(name: string, mimeType?: string, bytes?: Uint8Array): boolean {
   if (bytes && isPdfMagic(bytes)) return true;
   if (mimeType === "application/pdf") return true;
   if (/\.pdf$/i.test(name)) return true;
   return false;
 }

 let _cachedTessLangDir: string | null = null;
 function getTessLangDir(): string {
   if (_cachedTessLangDir && existsSync(_cachedTessLangDir)) {
     return _cachedTessLangDir;
   }
   const dir = join(tmpdir(), "reqflow-tessdata");
   mkdirSync(dir, { recursive: true });

   const engMeta = require("@tesseract.js-data/eng") as { langPath: string };
   const deuMeta = require("@tesseract.js-data/deu") as { langPath: string };

   const engSrc = join(engMeta.langPath, "eng.traineddata.gz");
   const deuSrc = join(deuMeta.langPath, "deu.traineddata.gz");
   const engDst = join(dir, "eng.traineddata.gz");
   const deuDst = join(dir, "deu.traineddata.gz");

   if (!existsSync(engDst) && existsSync(engSrc)) {
     copyFileSync(engSrc, engDst);
   }
   if (!existsSync(deuDst) && existsSync(deuSrc)) {
     copyFileSync(deuSrc, deuDst);
   }

   _cachedTessLangDir = dir;
   return dir;
 }

 interface TextFragment {
   str: string;
   x: number;
   y: number;
   width: number;
   height: number;
 }

 function assemblePageText(fragments: TextFragment[]): string {
   if (fragments.length === 0) return "";

   // Sort fragments by y descending (top to bottom in PDF coordinate space)
   const sorted = [...fragments].sort((a, b) => {
     const dy = b.y - a.y;
     if (Math.abs(dy) > 3) return dy;
     return a.x - b.x;
   });

   const lines: TextFragment[][] = [];
   for (const frag of sorted) {
     const line = lines.find((l) => {
       const lineY = l[0]!.y;
       const tol = Math.max(frag.height * 0.5, 3);
       return Math.abs(frag.y - lineY) <= tol;
     });

     if (line) {
       line.push(frag);
     } else {
       lines.push([frag]);
     }
   }

   // Sort lines top-to-bottom
   lines.sort((a, b) => b[0]!.y - a[0]!.y);

   const lineStrings: string[] = [];
   for (const line of lines) {
     line.sort((a, b) => a.x - b.x);
     let lineStr = "";
     for (const f of line) {
+      const cleanStr = f.str.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, " ");
+      if (!cleanStr) continue;
       if (!lineStr) {
-        lineStr = f.str;
+        lineStr = cleanStr;
       } else {
-        const needsSpace = !lineStr.endsWith(" ") && !f.str.startsWith(" ");
-        lineStr += (needsSpace ? " " : "") + f.str;
+        const needsSpace = !lineStr.endsWith(" ") && !cleanStr.startsWith(" ");
+        lineStr += (needsSpace ? " " : "") + cleanStr;
       }
     }
-    if (lineStr.trim()) {
-      lineStrings.push(lineStr.trimEnd());
+    const trimmed = lineStr.replace(/[ \t]+/g, " ").trimEnd();
+    if (trimmed) {
+      lineStrings.push(trimmed);
     }
   }

   return lineStrings.join("\n");
 }

 export async function readPdf(
   name: string,
   bytes: Uint8Array,
   options: ReadPdfOptions = {},
 ): Promise<ReadPdfOutput> {
   if (bytes.byteLength > MAX_FILE_SIZE_BYTES) {
     throw new Error(
       `"${name}" exceeds the maximum PDF size limit of 30MB (${(bytes.byteLength / (1024 * 1024)).toFixed(1)}MB).`,
     );
   }

   if (!isPdfMagic(bytes)) {
     throw new Error(`"${name}" is not a valid PDF file.`);
   }

   // Ensure Node globals exist before importing pdfjs
   const canvasModule = await import("@napi-rs/canvas");
   const g = globalThis as unknown as Record<string, unknown>;
   if (typeof g.DOMMatrix === "undefined" && canvasModule.DOMMatrix) {
     g.DOMMatrix = canvasModule.DOMMatrix;
   }
   if (typeof g.ImageData === "undefined" && canvasModule.ImageData) {
     g.ImageData = canvasModule.ImageData;
   }
   if (typeof g.Path2D === "undefined" && canvasModule.Path2D) {
     g.Path2D = canvasModule.Path2D;
   }
   if (typeof g.Image === "undefined" && canvasModule.Image) {
     g.Image = canvasModule.Image;
   }

   // Dynamically import pdfjs
   const pdfjs = await import("pdfjs-dist/legacy/build/pdf.mjs");
   const workerSrc = require.resolve("pdfjs-dist/legacy/build/pdf.worker.mjs");
   pdfjs.GlobalWorkerOptions.workerSrc = workerSrc;

   const loadingTask = pdfjs.getDocument({
     data: bytes,
-    isEvalSupported: false,
     disableFontFace: true,
     enableXfa: false,
-    useSystemFonts: true,
+    useSystemFonts: false,
+    ...( { isEvalSupported: false } as any ),
   });

   if (options.signal) {
     options.signal.addEventListener("abort", () => loadingTask.destroy(), { once: true });
     options.signal.throwIfAborted();
   }

   let doc;
   try {
